chapters.css:
/* ch01 */

.stairs .node { fill: var(--paper); stroke: var(--ink); stroke-width: 1.6; }
.stairs .edge { stroke: var(--ink); stroke-width: 1.8; fill: none; stroke-linecap: round; }
.stairs .edge.cut { stroke: var(--ink-soft); stroke-width: 1.2; stroke-dasharray: 4 4; stroke-linecap: butt; }
.stairs .head { fill: var(--ink); }
.stairs .zero { stroke: var(--rule); stroke-width: 1; }
.stairs .walk { stroke: var(--ink); stroke-width: 1.8; fill: none; stroke-linejoin: round; }
.stairs .dot { fill: var(--ink); }
.stairs .gap { stroke: var(--ink); stroke-width: 1.2; fill: none; }
.stairs .dotted { stroke: var(--ink); stroke-width: 1.2; stroke-dasharray: 1.5 3; stroke-linecap: round; }
.stairs .soft { fill: var(--ink-soft); }
#fig-stairs .srow { grid-template-columns: 8.4em minmax(0, 1fr) 3.7em; }
/* the hidden reading copy of a formula at the end of a line must not widen the page on a phone */
mjx-assistive-mml { max-width: 100%; }
#st-cut { grid-column: 2 / 4; width: 100%; min-width: 0; font: inherit; font-size: 0.88em; color: var(--ink); background: var(--paper); border: 1px solid var(--rule); padding: 0.1em 0.2em; max-width: 100%; }
#st-cut:focus-visible { outline: 2px solid var(--ink); outline-offset: 1px; }
@media print { #st-cut { -webkit-appearance: none; appearance: none; border: 0; padding: 0; } }

/* ch02 */

/* Chapter 2: the three-panel split, pickers and readouts */
.srow.pick { grid-template-columns: minmax(0, 1fr); gap: 0.1em; }  /* the label above its menu, so the longest network name is not cut off */
.pickbox { font: inherit; color: var(--ink); background: var(--paper); border: 1px solid var(--ink); border-radius: 2px; padding: 0.12em 0.4em; min-width: 0; width: 100%; box-sizing: border-box; }
.key { margin: 0.4em 0 0; font-size: 0.86em; line-height: 1.4; color: var(--ink-soft); text-indent: 0; text-align: center; }
.pstats { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 0.12em 1em; margin: 0.3em 0 0; padding: 0.3em 0; border-top: 1.2px solid var(--ink); border-bottom: 1.2px solid var(--ink); font-variant-numeric: tabular-nums; }
.prose .pstats dt { font-weight: 400; }
.prose .pstats dd { margin: 0; text-align: right; }
.split .road { stroke: var(--ink); stroke-width: 1.5; fill: none; }
.split .road.zero { stroke-dasharray: 5 3; }
.split .head { fill: var(--ink); }
.split .town { fill: var(--paper); stroke: var(--ink); stroke-width: 1.3; }
.split .rl { font-variant-numeric: tabular-nums; }
.split .rl.halo { stroke-width: 7px; }  /* the diagonal's label sits on its road, as the printed one sits in a white box */
/* MathJax's hidden copy of a formula for screen readers is as wide as the formula and sits at its start; beside the right margin it widened a phone page by a few pixels */
mjx-assistive-mml { max-width: 1px; }
@media (max-width: 360px) { .act { white-space: normal; } }
/* the page-20 marker stands before Figure 2.3, outside any paragraph; give it the column to hang its number from */
.prose > .pg { display: block; position: relative; height: 0; }

/* ch03 */

/* Chapter 3: pickers, the network drawings, the readout lists */
.srow.pick { grid-template-columns: 5.9em minmax(0, 1fr); }
.pickbox { font: inherit; font-size: 0.96em; color: var(--ink); background: var(--paper); border: 1px solid var(--ink); border-radius: 2px; padding: 0.12em 0.4em; min-width: 0; width: 100%; box-sizing: border-box; }
input.pickbox { font-variant-numeric: tabular-nums; }
.controls.picks { grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr); }
.controls.picks.even { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
.even .srow.pick { grid-template-columns: 4.6em minmax(0, 1fr); }
@media (max-width: 600px) { .controls.picks, .controls.picks.even { grid-template-columns: minmax(0, 1fr); } }
.key { margin: 0.5em 0 0; font-size: 0.86em; line-height: 1.4; color: var(--ink-soft); text-indent: 0; }
.pstats { font-size: 0.94em; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 0.12em 1em; margin: 0.3em 0 0; padding: 0.3em 0; border-top: 1.2px solid var(--ink); border-bottom: 1.2px solid var(--ink); font-variant-numeric: tabular-nums; }
/* one readout per line: four columns wrapped most labels onto two lines, so this is no taller */
.pstats.wide { margin-top: 0.8em; max-width: 32em; }
.prose .pstats dt { font-weight: 400; }
.prose .pstats dd { margin: 0; text-align: right; }
.controls .note { margin: 0.5em 0 0; font-size: 0.88em; line-height: 1.4; color: var(--ink-soft); text-indent: 0; }
.net { cursor: default; }
#rd-svg { margin-inline: auto; }
#pw-net { max-width: 300px; margin-inline: auto; }
.net .e { fill: none; stroke: var(--ink); stroke-linecap: round; }
.net .e.none { stroke-dasharray: 5 4; stroke-linecap: butt; }
.net .band { fill: none; stroke: var(--bar); stroke-linecap: round; }
.net .node { fill: var(--paper); stroke: var(--ink); stroke-width: 1.4; }
.net .hit { fill: none; stroke: transparent; stroke-width: 18; cursor: pointer; pointer-events: stroke; }
.net .lab { text-anchor: middle; }
.net .strong { font-weight: 700; }
.net .plate { fill: var(--paper); }
.power { cursor: ew-resize; }
.power:focus-visible { outline-offset: 4px; }
.power .frame { fill: none; stroke: var(--ink); stroke-width: 1; }
.power .tick { stroke: var(--ink); stroke-width: 1; }
.power .ref { stroke: var(--ink); stroke-width: 1; stroke-dasharray: 1.5 3; opacity: 0.45; }
.power .l-ring, .power .l-chords, .power .l-complete { fill: none; stroke: var(--ink); stroke-linejoin: round; }
.power .l-ring { stroke-width: 2.2; stroke-dasharray: 1.6 2.4; opacity: 0.7; }
.power .l-chords { stroke-width: 1.7; stroke-dasharray: 6 3.5; opacity: 0.8; }
.power .l-complete { stroke-width: 1.7; }
.power .m-ring { fill: var(--paper); stroke: var(--ink); stroke-width: 1.3; }
.power .m-chords { fill: var(--ink); fill-opacity: 0.38; stroke: var(--ink); stroke-width: 1.1; }
.power .m-complete { fill: var(--ink); }
.power .yours { fill: none; stroke: var(--ink); stroke-width: 0.9; }
.power .cross { stroke: var(--ink); stroke-width: 1.7; stroke-linecap: round; }
.power .err { stroke: var(--ink); stroke-width: 1; }
.power .lgplate { fill: var(--paper); }
.power .chance { stroke: var(--ink); stroke-width: 0.9; stroke-dasharray: 1 3; stroke-linecap: round; }
.power.faded .l-ring, .power.faded .l-chords, .power.faded .l-complete { opacity: 0.35; }
.flags .bar::before { display: none; }
.flags .bar i { left: 0; }
.flags td:first-child { white-space: nowrap; }
/* the shared print rule hides range inputs; the seed is a number box and should print */
@media print { .srow.pick input.pickbox { visibility: visible; } }

/* ch04 */

/* Chapter 4: the tuner and the three towns */
.srow.pick { grid-template-columns: 6.9em minmax(0, 1fr); }
.srow.wolfrow { grid-template-columns: 6.9em minmax(0, 1fr) 3.6em; }
.srow.numrow { grid-template-columns: 2.6em minmax(0, 1fr); }
.pickbox { font: inherit; color: var(--ink); background: var(--paper); border: 1px solid var(--ink); border-radius: 2px; padding: 0.12em 0.4em; min-width: 0; width: 100%; box-sizing: border-box; }
input.pickbox { font-variant-numeric: tabular-nums; }
.chk { white-space: nowrap; }
.controls .note, .readout .note { margin: 0.5em 0 0; font-size: 0.88em; line-height: 1.4; color: var(--ink-soft); text-indent: 0; }
.pstats { display: grid; grid-template-columns: minmax(6em, 1fr) auto; gap: 0.12em 1em; margin: 0.3em 0 0; padding: 0.3em 0; border-top: 1.2px solid var(--ink); border-bottom: 1.2px solid var(--ink); font-variant-numeric: tabular-nums; }
.prose .pstats dt { font-weight: 400; }
.prose .pstats dd { margin: 0; text-align: right; overflow-wrap: anywhere; }
.readout { margin-top: 0.8em; font-size: 0.92em; }
.readout .table-wrap { margin: 0.5em 0 0; }
#fig-tunings .controls { grid-template-columns: minmax(0, 1fr); }
.sumwrap { margin: 0.3em 0 0; }
.tuner { cursor: ew-resize; }
.tuner:focus-visible { outline-offset: 4px; }
.tuner .zero { stroke: var(--ink-soft); stroke-width: 1; }
.tuner .pm { stroke: var(--rule); stroke-width: 1; }
.tuner .tk { fill: var(--ink-soft); }
.tuner .tb { fill: var(--bar); }
.tuner .tb.wolf { fill: var(--ink); fill-opacity: 0.72; }
.sheaf .ar { stroke: var(--ink); stroke-width: 2.2; }
.sheaf .arrowhead { fill: var(--ink); }
.sheaf .vn { fill: var(--paper); stroke: var(--ink); stroke-width: 2; }
.sheaf .en { fill: var(--paper); stroke: var(--ink); stroke-width: 1.4; }
.sumtab th.num, .sumtab td.num, .fifths td.num, .fifths th.num { text-align: right; }
.sumtab td:first-child { white-space: normal; }
.fifths td:first-child, .fifths td:nth-child(4) { white-space: nowrap; }
@media (max-width: 600px) { .fifths, .sumtab { font-size: 0.86em; } .fifths th, .fifths td, .sumtab th, .sumtab td { padding-inline: 0.18em; } }
/* on a phone the read-off menu takes the full column, so its longest entry is not cut, and the
   twelve-row table sizes its number columns to their figures, so its last column is not pushed off */
@media (max-width: 600px) { .readout .srow.pick { grid-template-columns: minmax(0, 1fr); gap: 0.1em; } .fifths .num { width: auto; } }
/* a file name in running text or a caption is not hyphenated */
.prose code { hyphens: none; -webkit-hyphens: none; }
/* print: the shared rule hides range inputs; the number boxes and the checkbox should print. The
   drawings print near the book's size, and the tuner, taller than a page with its tables, may break
   between its parts instead of leaving most of a page empty before it. */
@media print {
  .srow.pick input { visibility: visible; }
  .sheaf { max-width: 4.2in; margin-inline: auto; }
  .tuner { max-width: 4.6in; margin-inline: auto; }
  #fig-tunings { break-inside: auto; }
  #fig-tunings .tuner, #fig-tunings .ctl-block, #fig-tunings .readout .table-wrap { break-inside: avoid; }
}

/* ch05 */

.wk-pick { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0.3em 0.7em; margin-bottom: 0.4em; }
.wk-pick select, .wk-in input {
  font: inherit; color: var(--ink); background: var(--paper);
  border: 1px solid var(--rule); border-radius: 2px;
}
.wk-pick select { padding: 0.05em 0.3em; }
.wk-pair { display: inline-flex; align-items: baseline; gap: 0.5em; white-space: nowrap; }
.try .act { white-space: normal; }
@media print { .wk-sep { display: none; } }
.prose li .mi svg { max-width: 100%; height: auto; }
.prose mjx-assistive-mml { max-width: 100%; }
/* the page 60 marker stands between two blocks; give it the footing a paragraph gives the others */
.prose > .pg { display: block; position: relative; height: 0; }
.wk-in { margin-top: 0.55em; table-layout: fixed; width: 100%; }
.wk-in th:first-child, .wk-in td:first-child { width: 4.4em; }
.wk-in input { font-size: 0.88em; box-sizing: border-box; }
.wk-controls .btn { font-size: 0.86em; }
.wk-controls .buttons { gap: 0.35em; }
.wk-in input { width: 100%; min-width: 0; padding: 0.04em 0.2em; text-align: right; font-variant-numeric: tabular-nums; }
.wk-in input:focus-visible, .wk-pick select:focus-visible { outline: 1.5px solid var(--ink); outline-offset: 1px; }
.wk-in th.num, .wk-in td.num { width: auto; }
.wk-in td.num { padding-left: 0.15em; padding-right: 0.15em; }
.wk-in th.num { text-align: right; }
.wk-out { margin-bottom: 0.4em; }
.wk-out th.num, .wk-out td.num { width: auto; text-align: right; }
.wk-out td, .wk-out th { padding-left: 0.2em; padding-right: 0.2em; }
.wk-controls .verdict { min-height: 1.4em; }
.walk .step { stroke: var(--ink); stroke-width: 2; fill: none; }
.walk .zero { stroke: var(--rule); stroke-width: 1; }
.walk .dot { fill: var(--ink); }
.walk .ah { fill: var(--ink); }
.walk .gapbar { stroke: var(--ink); stroke-width: 1.4; }
.walk .soft { fill: var(--ink-soft); }
.walk .ghost { stroke: var(--ink-soft); stroke-width: 1; stroke-dasharray: 4 3; fill: none; }

/* ch06 */

.controls.one { grid-template-columns: minmax(0, 1fr); }
.key { margin: 0.5em 0 0.4em; font-size: 0.92em; color: var(--ink-soft); }
.key .sw { display: inline-block; width: 1.5em; height: 0.55em; margin: 0 0.35em 0 0.9em; vertical-align: 0.05em; }
.key .sw:first-child { margin-left: 0; }
.key .sw-light { background: var(--bar); }
.key .sw-dark { background: var(--ink); }
.key .sw-dot { width: 0.7em; height: 0.7em; border-radius: 50%; background: var(--ink); }
.sums { margin: 0.4em 0 0.2em; }
.sums th.num, .idx th.num, .idx td.num { text-align: right; }
.sums .num, .idx .num { width: auto; }
.sums td:first-child, .idx td:first-child { white-space: normal; }
.idx td:last-child { white-space: nowrap; }
.prose .center { position: relative; }
@media print { .webonly { break-after: avoid; } }
.idx { margin-bottom: 0.3em; }
.idx th, .idx td { padding-right: 0.5em; }
.modes { display: flex; flex-wrap: wrap; align-items: center; gap: 0.4em; margin: 0.4em 0 0.2em; }
.modelab { font-family: var(--caps); margin-right: 0.3em; }
.modes .btn[aria-pressed="true"] { background: var(--ink); color: var(--paper); }
#try-6-3 .mi { display: inline-block; max-width: 100%; overflow-x: auto; vertical-align: top; }
.try .act { white-space: normal; }
.webonly { font-style: italic; margin: 1em 0 0.2em; color: var(--ink-soft); font-size: 0.92em; }
.waterfall:focus-visible, .sweep:focus-visible { outline-offset: 4px; }

/* ch07 */

.controls.tri-controls { grid-template-columns: minmax(0, 1fr); }
.tri .tag { fill: var(--paper); stroke: none; }
.tri { max-width: 23em; margin: 0 auto; height: auto; }
.tri .node { fill: var(--paper); stroke: var(--ink); stroke-width: 1.6; }
.tri .edge { stroke: var(--ink); stroke-width: 3; stroke-linecap: round; }
.tri .edge.none { stroke-width: 1.4; stroke-dasharray: 5 4; stroke-linecap: butt; }
.avail th.c, .avail td { text-align: center; }
.avail td:first-child, .avail th:first-child { text-align: left; }
.avail input, .tie input { width: 1.05em; height: 1.05em; accent-color: var(--ink); }
.avail td:not(:first-child) { cursor: pointer; }
.tri-controls .btn i { font-family: var(--text); letter-spacing: 0; }
.srow.off { color: var(--ink-soft); }
.srow.off input[type="range"] { cursor: default; }
.srow.off input[type="range"]::-webkit-slider-runnable-track { background: repeating-linear-gradient(90deg, var(--ink-soft) 0 4px, transparent 4px 8px); }
.srow.off input[type="range"]::-webkit-slider-thumb { border: 1.2px dashed var(--ink-soft); }
.srow.off input[type="range"]::-moz-range-track { background: repeating-linear-gradient(90deg, var(--ink-soft) 0 4px, transparent 4px 8px); }
.srow.off input[type="range"]::-moz-range-thumb { border: 1.2px dashed var(--ink-soft); }
#fig-lambda-tri sup { line-height: 0; font-size: 0.72em; }
.pairs td.num, .pairs th.num { text-align: right; padding-left: 0.3em; padding-right: 0.3em; }
.pairs th, .pairs td { white-space: nowrap; }
@media (max-width: 430px) { .tri-controls .pairs { font-size: 0.85em; } .pairs td, .pairs th, .pairs td.num, .pairs th.num { width: auto; padding-left: 0.12em; padding-right: 0.12em; } }
@media print { .tri-controls .noprint, #fig-lambda-tri .checks { display: none !important; } }
/* the page-79 and page-81 markers stand outside any paragraph; give them the column to hang their numbers from (as Chapter 2 does), or between 760 and 950 px the number widens the page */
.prose > .pg { display: block; position: relative; height: 0; }
.table-scroll { overflow-x: auto; margin-top: 0.5em; }
.tie { margin: 0.3em 0 0; }
.loopline { margin: 0.5em 0 0.1em; }
.checks { margin-top: 0.6em; font-size: 0.92em; color: var(--ink-soft); }
#tri-seed { width: 6em; font: inherit; color: var(--ink); background: var(--paper); border: 1px solid var(--ink-soft); padding: 0 0.3em; }

/* ch08 */
mjx-assistive-mml { max-width: 100%; }
.prose code { hyphens: none; -webkit-hyphens: none; }

/* ch09 */

.c9cycle .cyc { fill: none; stroke: var(--ink); stroke-width: 2.4; stroke-linejoin: round; }
.c9cycle .node { fill: var(--paper); stroke: var(--ink); stroke-width: 1.4; }
.c9cycle .cell { fill: var(--paper); stroke: var(--ink); stroke-width: 0.7; }
.c9cycle .cell.pos { fill: color-mix(in srgb, var(--ink) 20%, var(--paper)); }
.c9cycle .halo { paint-order: stroke; stroke: var(--paper); stroke-width: 4px; stroke-linejoin: round; }
.c9cycle .num { font-variant-numeric: lining-nums; }
.srow.selrow { grid-template-columns: auto minmax(0, 1fr); }
.srow.selrow select { font: inherit; color: var(--ink); background: var(--paper); border: 1px solid var(--rule); padding: 0.2em 0.3em; max-width: 100%; min-width: 0; }
.c9-out p { margin: 0.3em 0 0; line-height: 1.4; }
.c9-out .kind { font-style: italic; }
.prose mjx-assistive-mml { max-width: 100%; }
@media print { .srow.selrow select { -webkit-appearance: none; appearance: none; border: 0; padding: 0; } }
.tetra .sface { stroke: var(--ink); stroke-width: 0.8; stroke-linejoin: round; }

/* ch10 */

.recentre { cursor: default; }
.recentre .wedge { fill: var(--face); stroke: var(--ink-soft); stroke-width: 1.2; }
.recentre .wedge-t { fill: none; stroke: var(--ink); stroke-width: 1.2; stroke-dasharray: 5 4; }
.recentre .frame { fill: none; stroke: var(--ink); stroke-width: 1; }
.recentre .p-out { fill: var(--ink); }
.recentre .p-in { fill: none; stroke: var(--ink-soft); stroke-width: 0.8; }
.recentre .mark { fill: none; stroke: var(--ink); stroke-width: 1.8; }
.recentre .truth { fill: var(--ink); cursor: grab; }
.recentre.grabbing .truth { cursor: grabbing; }
.recentre .lblbg { fill: var(--paper); }
.recentre .link { fill: none; stroke: var(--ink-soft); stroke-width: 1; stroke-dasharray: 2 3; }
.recentre .pimark { fill: var(--paper); stroke: var(--ink); stroke-width: 1.3; }
.recentre-res[hidden] { display: none; }
.recentre-res { margin-top: 0.6em; }
.recentre-res th.num, .recentre-res td.num { text-align: right; width: auto; }

/* ch11 */

.map { cursor: crosshair; }
.map .frame { fill: none; stroke: var(--ink); stroke-width: 1; }
.map .tick { stroke: var(--ink); stroke-width: 1; }
.map .g-both { opacity: 0.42; }
.map .g-pool { opacity: 0.15; }
.map .g-both polygon, .map .g-pool polygon { fill: var(--ink); stroke: var(--ink); stroke-width: 0.6; stroke-linejoin: round; }
.map .r-def { fill: url(#mp-hatch); }
.map .hatch { stroke: var(--ink); stroke-width: 1.1; opacity: 0.6; }
.map .bnd-def { stroke: var(--ink); stroke-width: 1.6; }
.map .bnd-pool { stroke: var(--ink); stroke-width: 1.6; stroke-dasharray: 5 3; }
.map .edge { stroke: var(--ink); stroke-width: 1.6; opacity: 0.7; }
.map .ref { stroke: var(--ink); stroke-width: 1; stroke-dasharray: 1.5 3; }
.map .pt { fill: var(--paper); stroke: var(--ink); stroke-width: 1.8; }
.map .ptline { stroke: var(--ink); stroke-width: 1; stroke-dasharray: 3 3; }
.map text { paint-order: stroke; }
.controls select { font: inherit; color: var(--ink); background: var(--paper); border: 1px solid var(--ink); border-radius: 2px; padding: 0.1em 0.2em; max-width: 100%; min-width: 0; }
.controls.stack { grid-template-columns: minmax(0, 1fr); }
.controls select { width: 100%; }
.verd { margin-top: 0.6em; }
.tag { white-space: nowrap; font-family: var(--caps); font-size: 0.88em; border: 1px solid var(--ink); padding: 0 0.35em; border-radius: 2px; }
.tag.bad { background: var(--ink); color: var(--paper); }
#fig-map .shares th:first-child, #fig-map .shares td:first-child { white-space: normal; }

/* ch12 */

.asm-row { display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr); gap: 0.5em 1.2em; align-items: end; }
@media (max-width: 600px) { .asm-row { grid-template-columns: minmax(0, 1fr); } }
.asm .frame { fill: none; stroke: var(--rule); stroke-width: 1; }
.asm .bub { fill: var(--ink-soft); }
.asm .blab { fill: var(--paper); font-size: 10.5px; }
.asm .m { fill: var(--ink-soft); }
.asm .arrow { fill: none; stroke: var(--ink); stroke-width: 1.8; }
.asm .tick { stroke: var(--ink); stroke-width: 1; }
.asm .curve { stroke: var(--ink); stroke-width: 1.6; }
.asm .ref { stroke: var(--ink-soft); stroke-width: 1; stroke-dasharray: 1.5 3; }
.asm .cur { fill: var(--ink); }
.srow.sel { grid-template-columns: minmax(0, 1fr); gap: 0.1em; margin: 0.3em 0; }
.controls select { font: inherit; width: 100%; min-width: 0; color: var(--ink); background: var(--paper); border: 1px solid var(--ink); border-radius: 2px; padding: 0.1em 0.2em; }
.asm-stats td, .asm-stats th { font-size: 0.95em; }
.verdict i { font-style: italic; }

/* ch13 */

.q13 .srow { grid-template-columns: 5.6em minmax(0, 1fr) 3em; }
.q13 #q-prows .srow, .q13 #q-qrows .srow { grid-template-columns: 2.2em minmax(0, 1fr) 3em; }
.q13 #q-qrows { margin-top: 0.5em; }
.q13 select { font: inherit; color: var(--ink); background: var(--paper); border: 1px solid var(--ink); border-radius: 0; padding: 0.1em 0.3em; max-width: 100%; }
.q13 .srow.selrow { grid-template-columns: 5.6em minmax(0, 1fr); }
